import type { VersionedRecord, VersionRef } from "@/lib/versioning/types";
import { generateCanonicalId } from "@/lib/versioning/id";

/**
 * PRIORITY B8 — the Simulation Result model. Write-once: a result is
 * generated by exactly one simulation run and never edited afterward — see
 * simulation/engine.ts. Every metric here is either directly computed by
 * the engine from real simulated hands, or explicitly typed `undefined`
 * when not applicable (never a fabricated placeholder number — Priority
 * B8's own "do not fabricate unsupported metrics" rule).
 */

export interface RiskMetrics {
  /** Standard deviation of per-hand outcome, in betting units. */
  standardDeviation: number;
  /** Standard error of the mean EV estimate (standardDeviation / sqrt(handsSimulated)). */
  standardError: number;
  /** 95% confidence interval for the EV estimate, in betting units — [low, high]. */
  confidenceInterval95: [number, number];
  /** Probability-of-ruin estimate given the scenario's startingBankrollUnits — omitted when bankroll is 0 (undefined, not meaningful) or the engine did not compute it for this run. */
  riskOfRuinPercent?: number;
}

export interface SimulationResult extends VersionedRecord {
  scenarioId: string;
  scenarioVersion: number;
  seed: number;
  simulatorVersion: string;
  gameDefinitionRef: VersionRef;
  countMethodRef: VersionRef;
  bettingStrategyRef: VersionRef;
  playingStrategyRef: VersionRef;
  handsSimulated: number;
  /** Expected value per hand, in betting units — mean outcome across all simulated hands. */
  expectedValuePerHand: number;
  /** Total EV across the whole run (expectedValuePerHand * handsSimulated) — provided alongside the per-hand figure since both are useful at a glance. */
  totalExpectedValue: number;
  variance: number;
  risk: RiskMetrics;
  penetrationPercentUsed: number;
  /** BC/PE/IC — provided ONLY when the CountMethodDefinition referenced actually states them (see countMethodRegistry.ts's own fields); omitted, never estimated by the simulation itself, when the method's own definition doesn't state them. */
  bettingCorrelation?: number;
  playingEfficiency?: number;
  insuranceCorrelation?: number;
  runtimeMs: number;
  /** Every card-conservation/validation check the engine ran during this result's generation, and whether each passed — see simulation/engine.ts's own validation suite (Priority B7). A result with any `false` here must never be presented as trustworthy. */
  validationChecks: { name: string; passed: boolean }[];
  notes?: string;
}

/** True only when every entry in `validationChecks` passed — the one gate a UI/report should check before treating a result as usable, per Priority B7's "millions of simulations are worthless if rules are wrong." */
export function isResultTrustworthy(result: SimulationResult): boolean {
  return result.validationChecks.length > 0 && result.validationChecks.every((c) => c.passed);
}

export function buildSimulationResultId(): string {
  return generateCanonicalId();
}
